# -*- coding: utf-8 -*-
# (speaker, italiano, coreano); speaker None => didascalia, "#" => titolo di scena (nessuno dei due conta come battuta)
M, RB, FR, C, F, S = "Matteo", "Rebecca", "Frank", "Chiara", "Filippo", "Sal"
D = [
("#", "Scena 1 — Lunedì 20 ottobre, ore 7.30. Caffè Lucia, Mulberry Street, New York.", "장면 1 — 10월 20일 월요일 오전 7시 30분. 뉴욕 멀베리 스트리트, 카페 루치아."),
(None, "Un bancone di marmo, foto in bianco e nero di Napoli alle pareti, una macchina da espresso del 1962. Matteo ha dormito quattro ore. Ha con sé una sola borsa campione: una Scandicci in tobacco.", "대리석 카운터, 벽에는 나폴리의 흑백 사진, 1962년산 에스프레소 머신. 마테오는 네 시간을 잤다. 샘플 가방은 하나만 들고 왔다. 토바코 색 스칸디치."),
(S, "Buongiorno. Lei è italiano: l'ho capito da come guarda la macchina del caffè.", "안녕하세요. 이탈리아 분이시네. 커피 머신 보는 눈빛으로 알았어요."),
(M, "Fiorentino. E la macchina è più vecchia di mia madre. Un caffè normale, per favore. Cioè, un espresso.", "피렌체 사람이에요. 그리고 저 머신은 저희 어머니보다 나이가 많네요. 보통 커피 하나요. 그러니까, 에스프레소."),
(S, "Qui « normale » vuol dire mezzo litro con il latte. Ha fatto bene a correggersi.", "여기서 '보통'이라고 하면 우유 넣은 반 리터예요. 고쳐 말하길 잘하셨어요."),
(M, "Lei da quanto tempo è a New York?", "뉴욕엔 얼마나 계셨어요?"),
(S, "Dal settantotto. Sono di Napoli, quartiere Sanità. Sono solito dire che ho passato più anni qui che lì, ma il caffè lo faccio ancora come lì.", "78년부터요. 나폴리 사니타 동네 출신이에요. 여기서 산 해가 거기보다 길다고 늘 말하지만, 커피는 아직 거기식으로 만들어요."),
(M, "Ne vale la pena. È il primo caffè buono da quando sono atterrato.", "그럴 만해요. 착륙하고 처음 마시는 맛있는 커피예요."),
(S, "E quella borsa? Non è da turista.", "그 가방은요? 관광객 가방은 아닌데."),
(M, "È da lavoro. Alle dieci la faccio vedere a un grande magazzino, sulla Quinta. Hale & Whitcombe.", "일하는 가방이에요. 10시에 5번가 큰 백화점에 보여 줄 거예요. 헤일 앤드 휘트컴."),
(S, "Hale & Whitcombe. Mia nipote ci ha lavorato due anni. Dice che lì dentro parlano solo per numeri e per sigle.", "헤일 앤드 휘트컴이라. 우리 손녀가 거기서 2년 일했죠. 거기선 숫자랑 약자로만 말한대요."),
(M, "Per fortuna la buyer parla italiano. Bolognese, mi hanno detto.", "다행히 바이어가 이탈리아어를 해요. 볼로냐 말을 한다던데요."),
(S, "Allora casomai le servisse un caffè vero, la mandi da Sal. Sono io.", "그럼 혹시라도 진짜 커피가 필요하면 살한테 보내요. 그게 저예요."),
(None, "Il telefono di Matteo si illumina: videochiamata da Scandicci. Sono le tredici e trenta in Italia.", "마테오의 휴대폰이 켜진다. 스칸디치에서 영상 통화. 이탈리아는 오후 1시 30분이다."),
(F, "Sei vivo? Hai la faccia di uno che ha dormito in aereo con la borsa sulle ginocchia.", "살아 있냐? 비행기에서 가방 무릎에 올려놓고 잔 사람 얼굴이다."),
(M, "Ho dormito in aereo con la borsa sulle ginocchia. Non mi fidavo della cappelliera.", "비행기에서 가방 무릎에 올려놓고 잤어. 짐칸을 못 믿겠더라."),
(F, "Ricordati i tuoi limiti. Duecento borse al massimo per la primavera. Niente soldi per gli sconti degli altri. E niente resi.", "네 한계 기억해. 봄 시즌 최대 200개. 남의 할인에 쓸 돈 없음. 그리고 반품 없음."),
(M, "Lo so. E Omar mi ha mandato un messaggio stanotte: « Rebecca ti mangerà vivo, ma con educazione. »", "알아. 그리고 오마르가 밤에 메시지 보냈어. '레베카가 널 산 채로 먹을 거야. 예의 바르게.'"),
(F, "Allora mangia prima tu. Sal, giusto? Me lo nutra, per favore.", "그럼 네가 먼저 먹어. 살 씨 맞죠? 동생 좀 먹여 주세요."),
(S, "(al telefono) Ci penso io, dottore. Una sfogliatella e passa la paura.", "(전화에 대고) 제가 맡을게요, 선생. 스폴리아텔라 하나면 겁이 달아나요."),
(F, "Matteo, un'ultima cosa. Va da sé che non firmi niente oltre i centomila euro. Ma se ti chiedono qualcosa che non ti piace, alzati e vai a prendere un altro caffè da Sal.", "마테오, 마지막 하나. 10만 유로 넘는 건 서명 안 하는 거 말할 필요도 없지. 근데 마음에 안 드는 걸 요구하면, 일어나서 살한테 커피 한 잔 더 마시러 가."),
(M, "Il caffè di Sal come strategia di negoziazione.", "살의 커피를 협상 전략으로."),
(S, "Funziona da quarantasette anni. Chieda a tutti i miei clienti.", "47년째 통하는 거예요. 제 손님들한테 다 물어봐요."),

("#", "Scena 2 — Ore 10. Hale & Whitcombe, Quinta Strada, trentaquattresimo piano. Ufficio acquisti accessori.", "장면 2 — 오전 10시. 5번가 헤일 앤드 휘트컴 34층. 액세서리 구매팀 사무실."),
(None, "Pareti di vetro, campioni di borse in fila su scaffali bianchi, ciascuno con un cartellino a codice a barre. Rebecca Lanzi Hart, quarant'anni, capelli corti, scarpe da ginnastica sotto un tailleur nero, si alza e gli stringe la mano forte.", "유리 벽, 흰 선반 위에 줄지어 놓인 가방 샘플들, 하나하나에 바코드 택. 마흔 살 레베카 란치 하트가 짧은 머리에 검은 정장, 그 아래 운동화 차림으로 일어나 손을 세게 잡는다."),
(RB, "Matteo! Ciao, cinno. Omar mi ha detto che sei il più giovane della famiglia e il più testardo. Siediti. Hai quaranta minuti, poi ho un fornitore cinese.", "마테오! 안녕, 친노. 오마르가 그러던데 네가 집안 막내고 제일 고집 세다며. 앉아. 40분 있어. 그다음엔 중국 공급업체 미팅이야."),
(M, "Piacere, signora Lanzi Hart. Cinno?", "반갑습니다, 란치 하트 씨. 친노요?"),
(RB, "« Ragazzino », in bolognese. E niente « signora », per favore. A Bologna ho imparato il dialetto e il ragù. Il Lei, mai. Qui ci diamo tutti del tu, anche col presidente.", "볼로냐 말로 '꼬마'라는 뜻이야. 그리고 '부인'은 사양할게. 볼로냐에선 사투리랑 라구를 배웠지. 존댓말은 한 번도 안 배웠고. 여긴 다 반말해. 사장님한테도."),
(M, "Allora ciao, Rebecca. Ti ho portato una borsa sola.", "그럼 안녕, 레베카. 가방은 하나만 가져왔어."),
(RB, "Una sola? Gli altri fornitori me ne portano trenta.", "하나만? 다른 공급업체들은 서른 개씩 가져오는데."),
(M, "Gli altri fornitori non hanno Renzo. Questa è la Scandicci. Cucita da Renzo Paoli, controllata da Simone. C'è scritto sul cartellino.", "다른 공급업체엔 렌초가 없잖아. 이건 스칸디치야. 렌초 파올리가 꿰매고 시모네가 검사했어. 택에 적혀 있어."),
(RB, "(la gira, la apre, annusa l'interno) Okay. È bella. Lo dico una volta sola, poi parliamo di soldi. Prezzo?", "(돌려 보고, 열고, 안쪽 냄새를 맡으며) 오케이. 예쁘다. 딱 한 번만 말할게. 그다음은 돈 얘기야. 가격은?"),
(M, "Trecentotrenta euro franco fabbrica, Scandicci.", "스칸디치 공장 출고가 330유로."),
(RB, "Allora: con trasporto, assicurazione e dazi arriva qui a circa quattrocentoquaranta dollari. Noi lavoriamo a keystone: il doppio del costo sbarcato. In vetrina va a ottocentonovantacinque.", "그럼, 운송비, 보험, 관세 붙으면 여기 도착할 때 대략 440달러. 우린 키스톤으로 해. 도착 원가의 두 배. 매장에선 895달러에 걸리지."),
(M, "I dazi quanto sono, esattamente?", "관세는 정확히 얼마야?"),
(RB, "Dipende dalla voce doganale: cuoio, tela, dimensioni. Non lo calcoli tu, lo calcola il nostro spedizioniere. Tu mi dai il franco fabbrica e le schede tecniche. Il resto è un problema mio.", "세번(稅番)에 따라 달라. 가죽이냐 천이냐, 크기. 네가 계산하는 게 아니라 우리 운송 대리인이 해. 넌 공장 출고가랑 제품 사양서만 줘. 나머진 내 문제야."),
(M, "Ottocentonovantacinque dollari. A Seul la vendono a un milione e centonovantamila won. Siamo lì.", "895달러. 서울에선 119만 원에 팔아. 비슷하네."),
(RB, "Bene. Adesso la parte che non ti piacerà. Ho un manuale fornitori di sessanta pagine. Te lo riassumo in quattro parole: markdown, resi, penali, sostenibilità.", "좋아. 이제 네가 싫어할 부분. 공급업체 매뉴얼이 60쪽이야. 네 단어로 요약해 줄게. 마크다운, 반품, 위약금, 지속가능성."),
(M, "Cominciamo dalla prima.", "첫 번째부터."),
(RB, "I markdown. A fine stagione, quello che non vendiamo lo sconti del trenta, poi del cinquanta per cento. Il margine che perdiamo lo dividiamo con il fornitore. Si chiama « markdown money ». Lo pagano tutti.", "마크다운. 시즌 끝에 안 팔린 건 30%, 그다음 50% 할인해. 그때 잃는 마진을 공급업체랑 나눠. 그걸 '마크다운 머니'라고 해. 다들 내."),
(M, "Noi no.", "우린 안 내."),
(RB, "(alza un sopracciglio) Così, senza giri di parole?", "(눈썹을 치켜올리며) 그렇게 돌려 말하지도 않고?"),
(M, "Me l'hai detto tu: qui si parla diretto. Noi non paghiamo gli sconti degli altri. A Seul i nostri prezzi non scendono mai. Se una borsa Corsini va in saldo a Manhattan, il giorno dopo lo sanno a Seul, a Tokyo e a Dubai.", "네가 그랬잖아. 여긴 직설적으로 말한다고. 우린 남의 할인에 돈 안 내. 서울에서 우리 가격은 절대 안 내려가. 코르시니 가방이 맨해튼에서 세일하면 다음 날 서울, 도쿄, 두바이에서 다 알아."),
(RB, "Il mondo è piccolo, eh. E i resi? Return to vendor. Quello che non vendiamo dopo centoventi giorni, ve lo rimandiamo indietro. A vostre spese.", "세상 좁지. 그럼 반품은? 리턴 투 벤더. 120일 지나도 안 팔린 건 너희한테 돌려보내. 비용은 너희가."),
(M, "Nemmeno. Una borsa che attraversa l'oceano due volte non è più nuova. È stanca.", "그것도 안 돼. 바다를 두 번 건넌 가방은 더 이상 새것이 아니야. 지친 거지."),
(RB, "Una borsa stanca. Questa me la devo ricordare per il mio capo.", "지친 가방이라. 우리 상사한테 써먹으려면 기억해 둬야겠다."),
(M, "Però ti faccio una proposta. Dopo novanta giorni, puoi cambiare fino al dieci per cento dei pezzi con altri modelli. Non rimborso: cambio. Lo facciamo già con Seul e con Amsterdam.", "대신 제안 하나 할게. 90일 뒤에 물량의 10%까지 다른 모델로 바꿀 수 있어. 환불 말고 교환. 서울이랑 암스테르담하고도 이미 그렇게 해."),
(RB, "Cambio al dieci per cento. Mh. Più che un reso, è una seconda possibilità.", "10% 교환이라. 음. 반품이라기보다 두 번째 기회네."),
(M, "Esatto. Per la borsa e per voi.", "맞아. 가방한테도, 너희한테도."),
(RB, "Penali. Se la merce arriva in ritardo rispetto alla finestra di consegna, vi addebitiamo il tre per cento a settimana. Senza tetto.", "위약금. 물건이 납품 기간보다 늦게 오면 주당 3%를 청구해. 상한 없이."),
(M, "Il ritardo lo accetto. Senza tetto, no. Uno per cento a settimana, massimo cinque per cento. E il ritardo si conta dalla consegna a Livorno, non dall'arrivo al vostro magazzino: il mare non lo controllo io.", "지연 위약금은 받아들일게. 상한 없는 건 안 돼. 주당 1%, 최대 5%. 그리고 지연은 너희 창고 도착이 아니라 리보르노 인도 기준으로 따져. 바다는 내가 통제 못 하니까."),
(RB, "(scrive su un tablet) Due per cento, massimo sei.", "(태블릿에 적으며) 2%, 최대 6%."),
(M, "Uno e mezzo, massimo cinque.", "1.5%, 최대 5%."),
(RB, "Okay, uno e mezzo, massimo cinque. Visto? Si negozia in trenta secondi. A Bologna ci mettevamo un'ora e un piatto di tortellini.", "오케이, 1.5%, 최대 5%. 봤지? 30초면 협상이 끝나. 볼로냐에선 한 시간에 토르텔리니 한 접시가 필요했는데."),
(None, "Bussano. Entra un uomo sulla sessantina, cravatta allentata, un caffè americano in mano. Frank DeLuca, vicepresidente acquisti.", "노크 소리. 넥타이를 느슨하게 맨 60대 남자가 아메리카노를 들고 들어온다. 구매 담당 부사장 프랭크 들루카."),
(FR, "Rebecca, mi hanno detto che c'è un fiorentino che dice no a tutto. Dovevo vederlo.", "레베카, 다 '노'라고 하는 피렌체 사람이 왔다던데. 꼭 봐야겠더라고."),
(RB, "Frank, Matteo Corsini. Matteo, Frank DeLuca, il mio capo. Ha una nonna abruzzese e un italiano del millenovecentocinquanta.", "프랭크, 마테오 코르시니. 마테오, 우리 상사 프랭크 들루카. 아브루초 출신 할머니가 계시고 이탈리아어는 1950년식이야."),
(FR, "Della nonna Concetta, di Sulmona. Mi parlava solo in dialetto. Io rispondevo in inglese e lei mi tirava le orecchie.", "술모나 출신 콘체타 할머니. 사투리로만 말씀하셨지. 난 영어로 대답했고 할머니는 내 귀를 잡아당기셨어."),
(M, "Piacere, signor DeLuca. Mia nonna invece era di Scandicci e tirava le orecchie in fiorentino.", "반갑습니다, 들루카 씨. 저희 할머니는 스칸디치 분이셨고 피렌체 말로 귀를 잡아당기셨죠."),
(FR, "Allora siamo cugini. Rebecca, a che punto siete?", "그럼 우리 사촌이네. 레베카, 어디까지 왔어?"),
(RB, "Ha detto no ai markdown, no ai resi, ha tagliato le penali e mi ha offerto un cambio al dieci per cento. In dodici minuti.", "마크다운 거절, 반품 거절, 위약금 깎고 10% 교환을 제안했어요. 12분 만에."),
(FR, "Dodici minuti. Il fornitore cinese ci mette dodici minuti a salutare.", "12분이라. 중국 공급업체는 인사하는 데만 12분 걸리는데."),
(M, "Signor DeLuca, non diciamo no per principio. Diciamo no perché siamo piccoli. Poche mani esperte, non una fabbrica. Se pago i vostri sconti, devo alzare i prezzi a tutti gli altri.", "들루카 씨, 원칙 때문에 '노'라고 하는 게 아닙니다. 작아서 그래요. 숙련된 손 몇 개지 공장이 아니에요. 귀사 할인을 제가 내면 다른 모든 고객한테 가격을 올려야 해요."),
(FR, "E allora, perché dovremmo comprare da uno che non paga i markdown? Me lo dica in una frase.", "그럼 마크다운도 안 내는 사람한테서 왜 사야 하죠? 한 문장으로 말해 봐요."),
(M, "Perché le nostre borse non vanno in markdown. A Seul, al primo pop-up, ne abbiamo vendute cinquantadue su sessantuno in due settimane, con ventisei clienti in lista d'attesa.", "우리 가방은 마크다운까지 안 가니까요. 서울 첫 팝업에서 2주 만에 61개 중 52개가 팔렸고, 대기 손님이 26명이었어요."),
(FR, "(guarda Rebecca) Ventisei in lista d'attesa.", "(레베카를 보며) 대기 26명이라."),
(RB, "Ho verificato. Ho un'amica da Gaon. È vero.", "확인했어요. 가온에 아는 사람이 있거든요. 사실이에요."),
(FR, "Allora parliamo della quarta parola. La sostenibilità. Qui non è una moda, figliolo: è un obbligo. I nostri azionisti la chiedono, i nostri clienti la chiedono, e fra due anni la chiederà anche la legge.", "그럼 네 번째 단어 얘기하지. 지속가능성. 여기선 유행이 아니라 의무야, 젊은 친구. 주주들도 요구하고, 고객들도 요구하고, 2년 뒤엔 법도 요구할 거야."),
(M, "Usiamo concia al vegetale, il cuoio viene da una sola conceria, quella di Bini, a trenta chilometri. Sappiamo di quale partita è ogni pelle.", "저흰 식물성 무두질을 써요. 가죽은 30킬로미터 떨어진 비니 무두질 공장 한 곳에서만 와요. 가죽마다 어느 로트인지 알아요."),
(RB, "Bellissimo. Ce l'hai per iscritto? Con i numeri? Energia, acqua, rifiuti, persone?", "멋지다. 그거 문서로 있어? 숫자로? 에너지, 물, 폐기물, 사람?"),
(M, "Per iscritto… non ancora.", "문서로는… 아직."),
(RB, "Allora per ora è una bella storia. Le belle storie io le adoro, ma il mio ufficio legale no.", "그럼 지금은 좋은 이야기일 뿐이야. 난 좋은 이야기를 사랑하지만 우리 법무팀은 아니거든."),
(FR, "Facciamo così. Pausa pranzo. Lei si schiarisce le idee, noi pure. Alle due e mezza ci rivediamo con un numero.", "이렇게 하죠. 점심시간. 그쪽도 생각 정리하고 우리도 하고. 2시 반에 숫자 하나 들고 다시 봅시다."),

("#", "Scena 3 — Ore 12.45. Una panchina a Bryant Park. Videochiamata con Scandicci.", "장면 3 — 오후 12시 45분. 브라이언트 파크 벤치. 스칸디치와 영상 통화."),
(None, "Matteo mangia un panino in piedi, poi si siede. Sullo schermo, Chiara in laboratorio, con dietro il banco di Renzo. Filippo si affaccia dalla porta.", "마테오가 선 채로 샌드위치를 먹다가 앉는다. 화면에는 공방의 키아라, 뒤로 렌초의 작업대. 필리포가 문가에서 고개를 내민다."),
(C, "Allora? Ti hanno mangiato vivo?", "그래서? 산 채로 먹혔어?"),
(M, "Con educazione, come aveva detto Omar. Markdown e resi li ho rifiutati. Penali: uno e mezzo a settimana, massimo cinque. Il problema è la sostenibilità: vogliono numeri scritti.", "오마르 말대로 예의 바르게. 마크다운이랑 반품은 거절했어. 위약금은 주당 1.5%, 최대 5%. 문제는 지속가능성이야. 숫자로 된 문서를 원해."),
(C, "I numeri ce li ha Lorenzo, sparsi in venti fogli. Bini ha i certificati della concia. Non li abbiamo mai messi insieme.", "숫자는 로렌초가 갖고 있어. 종이 스무 장에 흩어져서. 비니한테 무두질 인증서가 있고. 한 번도 한데 모아 본 적이 없을 뿐이야."),
(F, "(dalla porta) Non promettere quello che non hai, Matteo.", "(문가에서) 없는 걸 약속하지 마, 마테오."),
(M, "Non prometto. Ma sono solito dare una data quando non ho una cosa. Una data si può rispettare.", "약속 안 해. 근데 난 없는 게 있을 땐 날짜를 주는 편이야. 날짜는 지킬 수 있으니까."),
(C, "E poi ti serve un'altra cosa. Hai detto che il capo ha una nonna abruzzese?", "그리고 하나 더 필요해. 상사한테 아브루초 출신 할머니가 계시다고 했지?"),
(M, "Di Sulmona. Gli tirava le orecchie.", "술모나. 귀를 잡아당기셨대."),
(C, "Allora non mandargli un catalogo. Mandagli le mani di Renzo. Giulia ha girato un video la settimana scorsa: tre minuti, Renzo che cuce una Domenica dall'inizio alla fine. Senza musica. Si sente solo l'ago.", "그럼 카탈로그 보내지 마. 렌초 손을 보내. 줄리아가 지난주에 영상 찍었어. 3분짜리, 렌초가 도메니카 하나를 처음부터 끝까지 꿰매는 거. 음악 없이. 바늘 소리만 들려."),
(M, "Per i venditori del negozio. Per spiegare ai commessi perché costa ottocentonovantacinque dollari.", "매장 판매 직원용으로. 왜 895달러인지 직원들한테 설명하게."),
(C, "Esatto. Un video di formazione. Così i commessi non dicono « è di pelle », ma « è di Renzo ».", "그렇지. 교육 영상. 그러면 직원들이 '가죽이에요'가 아니라 '렌초 거예요'라고 말하겠지."),
(F, "E se ti chiedono più di duecento borse?", "그리고 200개 넘게 달라고 하면?"),
(M, "Ne chiedo meno io. Con Omar a febbraio e Seul a gennaio, centocinquanta è già tanto.", "내가 먼저 적게 부를 거야. 2월에 오마르, 1월에 서울 있으니 150개도 이미 많아."),
(F, "Centocinquanta. Bene. Casomai insistessero, ricordati del caffè di Sal.", "150개. 좋아. 혹시라도 계속 밀어붙이면 살의 커피를 기억해."),
(C, "Chi è Sal?", "살이 누군데?"),
(M, "Un napoletano che fa il caffè da quarantasette anni sulla stessa macchina. Ti piacerebbe: non cambia mai niente.", "같은 머신으로 47년째 커피 내리는 나폴리 사람. 너도 좋아할 거야. 절대 아무것도 안 바꿔."),
(C, "Allora portagliene una, di borsa. Così ha qualcosa da non cambiare.", "그럼 그 사람한테 가방 하나 갖다줘. 바꾸지 않을 게 하나 더 생기게."),
(M, "Una Collina in tobacco. Gli starebbe bene dietro il bancone.", "토바코 콜리나. 카운터 뒤에 잘 어울리겠다."),
(C, "Gliela spedisco con l'ordine di febbraio. Cartellino: « Scelta da Matteo, per Sal ». Come quello di Watanabe.", "2월 주문이랑 같이 보낼게. 택은 '마테오가 고름, 살에게'. 와타나베 거처럼."),
(F, "E chi la paga, questa Collina?", "그 콜리나는 누가 내는데?"),
(C, "Tu, Fili. Il direttore generale offre.", "오빠가, 필리. 총괄 사장님이 쏘는 거야."),
(M, "La pago io, me la tolgo dallo stipendio. Così nel foglio di Lorenzo non c'è un regalo senza nome.", "내가 낼게. 월급에서 뺄게. 그래야 로렌초 종이에 이름 없는 선물이 안 생기지."),
(C, "Bravo. E adesso rientra, che alle due e mezza hai bisogno di tutta la tua faccia tosta.", "잘했어. 이제 들어가. 2시 반엔 그 뻔뻔함이 전부 필요할 테니까."),

("#", "Scena 4 — Ore 14.30. Hale & Whitcombe, sala riunioni.", "장면 4 — 오후 2시 30분. 헤일 앤드 휘트컴, 회의실."),
(None, "Rebecca ha stampato una tabella. Frank ha tolto la giacca. Matteo appoggia il telefono sul tavolo, con il video di Renzo pronto.", "레베카는 표 한 장을 출력해 왔다. 프랭크는 재킷을 벗었다. 마테오는 렌초의 영상을 띄워 둔 휴대폰을 테이블에 내려놓는다."),
(RB, "Il nostro numero: duecentocinquanta borse per la primavera. Quattro modelli. Consegna in negozio entro il primo aprile.", "우리 숫자. 봄 시즌 250개. 모델 네 개. 4월 1일까지 매장 입고."),
(M, "Il mio: centocinquanta. Tre modelli: sessanta Scandicci, cinquanta Domenica, quaranta Collina. Partenza dal porto di Livorno a metà febbraio, via mare. Da voi a metà marzo.", "내 숫자. 150개. 모델 세 개. 스칸디치 60, 도메니카 50, 콜리나 40. 2월 중순 리보르노항에서 해상 출발. 너희한테는 3월 중순 도착."),
(RB, "Centocinquanta? Matteo, ottocentonovantacinque dollari per centocinquanta borse non riempiono neanche un angolo del nostro piano.", "150개? 마테오, 895달러짜리 150개로는 우리 층 구석 하나도 못 채워."),
(M, "Un angolo basta. Preferisco un angolo vuoto a fine stagione che un tavolo di saldi.", "구석 하나면 충분해. 시즌 끝에 세일 테이블보다는 빈 구석이 나아."),
(FR, "Un angolo vuoto. La nonna Concetta diceva: « Meglio la fame che la roba avanzata. »", "빈 구석이라. 콘체타 할머니가 그러셨지. '남는 것보다 배고픈 게 낫다.'"),
(M, "Ed è per questo che vorrei mostrarvi tre minuti. Non di parole.", "그래서 3분만 보여 드리고 싶어요. 말 말고요."),
(None, "Il video parte. Le mani di Renzo, le dita un po' storte, l'ago che entra ed esce dal cuoio. Il rumore del filo tirato. Nessuno parla per tre minuti.", "영상이 시작된다. 조금 굽은 렌초의 손가락, 가죽을 드나드는 바늘. 실을 당기는 소리. 3분 동안 아무도 말하지 않는다."),
(FR, "(si schiarisce la voce) Quanti anni ha, quell'uomo?", "(목을 가다듬으며) 저분 연세가 어떻게 되시나?"),
(M, "Settantadue. Lavora a quel banco dal sessantasei. Ha l'artrite, ma il punto non cambia.", "일흔둘이요. 66년부터 저 작업대에서 일하셨어요. 관절염이 있지만 바늘땀은 안 바뀌어요."),
(FR, "Mia nonna cuciva così. Le federe, però, non le borse.", "우리 할머니도 저렇게 꿰매셨지. 가방 말고 베갯잇이었지만."),
(M, "Questo video lo diamo ai vostri commessi. Formazione gratuita. E se volete, a marzo vengo io a spiegare ogni borsa, per due giorni.", "이 영상을 귀사 판매 직원들한테 드릴게요. 무료 교육이에요. 원하시면 3월에 제가 와서 이틀 동안 가방 하나하나 설명할게요."),
(RB, "Questa non me l'aspettavo. I fornitori di solito ci mandano un PDF.", "이건 예상 못 했다. 보통 공급업체들은 PDF를 보내거든."),
(FR, "Rebecca. Centocinquanta. Niente markdown money, cambio al dieci per cento dopo novanta giorni, penali uno e mezzo con tetto al cinque. Il pagamento?", "레베카. 150개. 마크다운 머니 없음, 90일 뒤 10% 교환, 위약금 1.5%에 상한 5%. 지급은?"),
(RB, "Noi paghiamo a novanta giorni dalla consegna. Standard.", "우린 인도 후 90일 지급이에요. 표준이죠."),
(M, "Novanta giorni sono la vita di una borsa. Trenta per cento all'ordine, il resto a quarantacinque giorni dalla consegna a Livorno.", "90일이면 가방 한 개의 일생이야. 주문 시 30%, 나머지는 리보르노 인도 후 45일."),
(RB, "Sessanta, e niente acconto.", "60일, 그리고 선금 없음."),
(M, "Venti per cento all'ordine, il resto a sessanta.", "주문 시 20%, 나머지 60일."),
(RB, "(guarda Frank, che annuisce) Venti e sessanta. Okay.", "(고개를 끄덕이는 프랭크를 보며) 20%에 60일. 오케이."),
(FR, "Allora abbiamo un accordo per la primavera. Ma c'è una cosa che Rebecca deve dirLe, e non è negoziabile.", "그럼 봄 시즌 합의가 된 거네요. 하지만 레베카가 해야 할 말이 하나 있어요. 협상 불가예요."),
(RB, "Il nostro ufficio legale non firma l'ordine definitivo senza un documento. Il bilancio di sostenibilità. Concia, tracciabilità del cuoio, energia, persone. Con i numeri, non con le storie.", "우리 법무팀은 문서 없이 최종 주문에 서명 안 해. 지속가능성 보고서. 무두질, 가죽 추적성, 에너지, 사람. 이야기 말고 숫자로."),
(M, "Lo avrete. Non subito, ma lo avrete. Ve lo dico come lo direi a Seul: una data.", "드릴게요. 당장은 아니지만 드릴게요. 서울에서 말하듯이 말씀드리죠. 날짜로."),
(RB, "Allora la data la do io. Matteo, il bilancio di sostenibilità mandamelo entro dicembre. Altrimenti l'ordine di primavera resta sulla carta.", "그럼 날짜는 내가 정할게. 마테오, 지속가능성 보고서 12월까지 보내 줘. 안 그러면 봄 주문은 종이 위에만 남아."),
(M, "Entro dicembre. Senza aggettivi.", "12월까지. 형용사 없이."),
(RB, "Con qualche aggettivo, ti prego. Gli americani gli aggettivi li adorano. Ma ogni aggettivo con un numero accanto.", "형용사 좀 넣어 줘, 제발. 미국 사람들은 형용사를 사랑해. 대신 형용사마다 옆에 숫자 하나씩."),
(FR, "(si alza, gli stringe la mano) Corsini, sa una cosa? Non ho mai comprato da uno che mi ha detto no cinque volte in una mattina.", "(일어나 악수하며) 코르시니, 그거 알아요? 아침 한나절에 '노'를 다섯 번 한 사람한테서 사 본 적이 없어요."),
(M, "E ne valeva la pena?", "그럴 만했나요?"),
(FR, "Lo sapremo a marzo. Ma la nonna Concetta avrebbe comprato.", "3월에 알게 되겠죠. 하지만 콘체타 할머니라면 사셨을 거예요."),
(RB, "E adesso il caffè lo offro io. Uno vero, non quello del distributore.", "이제 커피는 내가 살게. 자판기 말고 진짜로."),
(M, "Conosco il posto giusto. Mulberry Street. Si chiama Sal.", "딱 맞는 데 알아. 멀베리 스트리트. 살이라고 해."),
(RB, "Sal di Caffè Lucia? Ci andavo a vent'anni, quando tornavo da Bologna e mi mancava l'Italia.", "카페 루치아의 살? 스무 살 때 볼로냐에서 돌아와서 이탈리아가 그리울 때 가던 데야."),
(M, "Allora è deciso. E Sal mi ha già detto che casomai ti servisse un caffè vero, dovevo mandarti da lui.", "그럼 정해졌네. 살이 벌써 그랬어. 혹시 진짜 커피가 필요하면 너를 자기한테 보내라고."),
(RB, "Il mondo è piccolo, cinno. Ma il mio dicembre è molto lungo. Non dimenticartelo.", "세상 좁다, 친노. 근데 내 12월은 아주 길어. 잊지 마."),
]

